// Sends report emails to shop owners.
import { loadReport, saveReport } from './store.js';
import { sendMail } from './mail.js';
import { renderCorrection, renderDaily, renderWeekly } from './report_render.js';

async function sendReport(kind, shop, key, html, subject) {
  const name = `${kind}-${shop.id}-${key}`;
  await saveReport(name, html);
  // Reading the report back from the store before mailing is deliberate: see docs/adr/0024-report-emails-are-sent-from-the-stored-copy.md
  const body = await loadReport(name);
  await sendMail(shop.email, subject, body);
  return { shopId: shop.id, kind, bytes: html.length };
}

export function sendDailyReport(shop, rows, day) {
  return sendReport('daily', shop, day, renderDaily(shop, rows, day), `Your report for ${day}`);
}

export function sendWeeklyReport(shop, rows, weekStart) {
  return sendReport('weekly', shop, weekStart, renderWeekly(shop, rows, weekStart), `Your report for the week of ${weekStart}`);
}

export function sendCorrection(shop, rows, day, note) {
  return sendReport('correction', shop, day, renderCorrection(shop, rows, day, note), `Corrected report for ${day}`);
}
